# %% [markdown]
# # CASMI 2026 — specs_scratch R1: coverage audit + class-vote diagnostic (Colab)
#
# **Generated by `scratch_pkg/tools/mk_notebook.py r1_audit_colab` from `scratch_pkg/drivers/r1_audit_colab.py` —
# do not hand-edit.** Gates pre-registered in `specs/specs_scratch/gate_report.md` (R1 section) before this run.
# Needs `casmi_2026/casmi26-scratch-pool/` from `casmi_scratch_r1_pool_colab.ipynb`.
#
# Runtime: **CPU, High-RAM** (the full train library is loaded). Each stage's result is saved to
# `casmi_2026/_r1_audit/`; a re-run skips finished stages.
#
# | stage | gate |
# |---|---|
# | coverage | R1.2 truth-in-window recall, slice I (enveda-np-examples): R0 vs R1a vs R1b; window growth (R1.3) |
# | truth_in_sim | R1.3 share of truths that the time budget would simulate (MetFrag-lite + sim priority, own spectra banned) |
# | cv | CV: class vote purity vs majority baseline and coverage, delta-list and open ±200 Da analog hits |
#
# Paste the final printout back into the chat.

# %%
import json, os, subprocess, sys, time
from pathlib import Path

from google.colab import drive
drive.mount("/content/drive")

ROOT = Path(os.environ.get("CASMI_INPUT", "/content/drive/MyDrive/casmi_2026"))
POOL_DIR = ROOT / "casmi26-scratch-pool"
OUT = ROOT / "_r1_audit"
WORKERS = os.cpu_count() or 2
PKG_FILES = None  # @@PKG_FILES@@
PKG_ROOT = Path("/content/pkg")
for rel, src in PKG_FILES.items():
    p = PKG_ROOT / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(src, encoding="utf-8")
sys.path.insert(0, str(PKG_ROOT))
OUT.mkdir(parents=True, exist_ok=True)

RDKIT_PIN = "2026.03.3"
PY_TAG = f"cp{sys.version_info.major}{sys.version_info.minor}"
RDKIT_WHL = next(iter(sorted(ROOT.glob(f"*/rdkit-*-{PY_TAG}-*.whl"))), None)
cmd = ([sys.executable, "-m", "pip", "install", "-q", "--no-deps", str(RDKIT_WHL)] if RDKIT_WHL is not None
       else [sys.executable, "-m", "pip", "install", "-q", f"rdkit=={RDKIT_PIN}"])
r_ = subprocess.run(cmd, capture_output=True, text=True)
if r_.returncode != 0:
    raise RuntimeError("rdkit install failed:\n" + r_.stdout[-2000:] + "\n" + r_.stderr[-2000:])
import rdkit  # noqa: E402
assert rdkit.__version__ == RDKIT_PIN, rdkit.__version__

import numpy as np  # noqa: E402

from casmi_scratch import audit  # noqa: E402
from casmi_scratch.config import Config  # noqa: E402
from casmi_scratch.library import load_library, remap_keys  # noqa: E402
from casmi_scratch.pool import build_r0_pool, load_keymap, load_np_labels, load_pool  # noqa: E402

CFG = Config().with_(frag_workers=WORKERS)
T0 = time.time()


def find(name):
    for depth in ("*", "*/*", "*/*/*"):
        hits = sorted(ROOT.glob(f"{depth}/{name}"), key=lambda p: len(str(p)))
        if hits:
            return hits[0]
    raise FileNotFoundError(f"{name} not found under {ROOT}")


def stage(name, fn):
    """Run fn() once; its JSON result is cached on Drive."""
    path = OUT / f"{name}.json"
    if path.exists():
        print(f"[{name}] cached")
        return json.loads(path.read_text())
    t = time.time()
    res = fn()
    path.write_text(json.dumps(res, indent=1, default=str))
    print(f"[{name}] {time.time() - t:.0f}s")
    return res


TRAIN = str(find("train.parquet"))
MANIFEST = json.loads((POOL_DIR / "MANIFEST.json").read_text())
MOLS = audit.load_slice(TRAIN)
KEYMAP = load_keymap(str(POOL_DIR))
R0_TRUTH = lambda ik: ik  # noqa: E731
R1_TRUTH = lambda ik: KEYMAP.get(ik, ik)  # noqa: E731
print(f"slice I: {len(MOLS)} molecules, {sum(len(s) for _, s in MOLS):,} spectra | pool {MANIFEST['version']}")

POOL0 = build_r0_pool(str(find("coco_meta.pkl").parent), TRAIN, workers=WORKERS)
POOL1A, INFO1A = load_pool(str(POOL_DIR))
POOL1B, INFO1B = load_pool(str(POOL_DIR), drop_e180=True)

# %% [markdown]
# ## R1.2 coverage and window growth

# %%
def run_coverage():
    rows = {n: audit.coverage(MOLS, p, tr, CFG) for n, p, tr in
            (("r0", POOL0, R0_TRUTH), ("r1a", POOL1A, R1_TRUTH), ("r1b", POOL1B, R1_TRUTH))}
    return dict(summary={n: audit.summarize_coverage(r) for n, r in rows.items()},
                growth_r1a=audit.growth(rows["r0"], rows["r1a"]), growth_r1b=audit.growth(rows["r0"], rows["r1b"]),
                pool_sizes=dict(r0=len(POOL0), r1a=len(POOL1A), r1b=len(POOL1B)))


COV = stage("coverage", run_coverage)
print(json.dumps(COV, indent=1))

# %% [markdown]
# ## R1.3 truth-in-simulated (sim budget of a real run, own library spectra banned)

# %%
LIB0 = load_library(TRAIN, struct_mass=CFG.struct_mass)
LIB1 = remap_keys(LIB0, KEYMAP)
REQ = audit.sim_budget_per_mol(CFG)
TIS = stage("truth_in_sim", lambda: dict(
    r0=audit.truth_in_sim(MOLS, LIB0, POOL0, R0_TRUTH, CFG, REQ),
    r1a=audit.truth_in_sim(MOLS, LIB1, POOL1A, R1_TRUTH, CFG, REQ),
    r1b=audit.truth_in_sim(MOLS, LIB1, POOL1B, R1_TRUTH, CFG, REQ)))
print(json.dumps(TIS, indent=1))

# %% [markdown]
# ## CV class-vote diagnostic (R2 candidate)

# %%
LABELS = load_np_labels(str(POOL_DIR))


def label_of(key, level):
    if key in LABELS.index:
        v = LABELS.at[key, level]
        return v if isinstance(v, str) and v else None
    return None


CV = stage("cv", lambda: audit.class_vote_diag(MOLS, LIB1, R1_TRUTH, label_of, CFG))
print(json.dumps(CV, indent=1))

# %% [markdown]
# ## Verdicts (pre-registered gates)

# %%
s = COV["summary"]
verdicts = {
    "R1.1 no loss (MANIFEST)": MANIFEST["R1_1"]["missing"] == 0,
    "R1.2 recall r1a >= r0": s["r1a"]["recall_window"] >= s["r0"]["recall_window"],
    "CV (a) delta list": CV["delta"]["pass"],
    "CV (b) open 200 Da": CV["open"]["pass"],
}
print(f"R1.1 lost R0 rows: {MANIFEST['R1_1']['missing']}")
print(f"R1.2 recall (window / scored / in pool): " + " | ".join(
    f"{n} {v['recall_window']:.3f} / {v['recall_scored']:.3f} / {v['in_pool']:.3f}" for n, v in s.items()))
print(f"R1.3 window median r0 {s['r0']['window_median']:.0f} -> r1a {s['r1a']['window_median']:.0f} "
      f"(p95 ratio {COV['growth_r1a']['ratio_p95']:.2f}); truth-in-sim r0 {TIS['r0']['truth_in_sim']:.3f} "
      f"r1a {TIS['r1a']['truth_in_sim']:.3f} r1b {TIS['r1b']['truth_in_sim']:.3f} (req/mol {REQ:.0f})")
for mode in ("delta", "open"):
    sc = CV[mode]["np_superclass"]
    print(f"CV {mode}: coverage {sc['coverage']:.3f} purity {sc['purity']:.3f} baseline {sc['baseline']:.3f} "
          f"(majority {sc['majority']}); pathway purity {CV[mode]['np_pathway']['purity']:.3f}")
for k, v in verdicts.items():
    print(f"  {'PASS' if v else 'FAIL'}  {k}")
(OUT / "verdicts.json").write_text(json.dumps(dict(verdicts=verdicts, total_s=round(time.time() - T0, 1)), indent=1))
